function msg(s){let n=$('#message');n.textContent=s;n.style.display='block';clearTimeout(msg.timer);msg.timer=setTimeout(()=>n.style.display='none',5000)}
function card(title,body){return '<section class="card"><h2>'+esc(title)+'</h2>'+body+'</section>'}
function input(k,a,b,type='text',value='',extra=''){return '<label>'+esc(t(a,b))+'<input name="'+k+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>'}
function select(k,a,b,opts){return '<label>'+esc(t(a,b))+'<select name="'+k+'">'+opts.map(([v,n])=>'<option value="'+esc(v)+'">'+esc(n)+'</option>').join('')+'</select></label>'}
