function form(kind,body){return '<form data-form="'+kind+'">'+body+'<button>'+esc(t('حفظ / تنفيذ','Save / run'))+'</button></form>'}
function table(headers,rows){return '<div class="table"><table><thead><tr>'+headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
