async function auroraHome(){let list=perms[user.role].filter(k=>['products','pos','orders','inventory','repairs','suppliers','warranty','builder','report'].includes(k));let content=auroraHero(t('أهلاً بك، ','Welcome, ')+user.name,t('مساحة عمل واحدة لإدارة المبيعات والمخزون وخدمة العملاء.','One workspace for sales, inventory and customer service.'));if(user.role==='admin'){try{const a=await api('report');content+='<div class="grid aurora-kpi">'+[['total','المبيعات','Sales'],['profit','الربح التقديري','Estimated profit'],['expense','المصاريف','Expenses'],['cost','التكلفة','Cost']].map(([k,ar,en])=>card(t(ar,en),'<div class="num">'+money(a[k])+'</div>')).join('')+'</div>'}catch(e){content+=info(e.message)}}content+='<h2>'+esc(t('إجراءات سريعة','Quick actions'))+'</h2><div class="aurora-quick">'+list.map(k=>'<button data-page="'+k+'">'+auroraIcon(k)+esc(label(k))+'</button>').join('')+'</div>';if(user.role==='admin')content+=card(t('إدارة المتجر المتكاملة','Full store management'),'<a class="button" href="./index.html?central=1">'+t('فتح جميع أقسام الإدارة السابقة','Open all previous administration modules')+'</a>'+info(t('احفظ تعديلاتك مركزياً بعد العمل في لوحة الإدارة السابقة.','Use central save after editing in the legacy admin.')));return content}

