function publishedView(site,media=[]){if(!site)return '';return '<div class="hero" style="background:linear-gradient(125deg,#101a35,'+esc(/^#[a-f0-9]{6}$/i.test(site.accent)?site.accent:'#1768db')+')"><h1>'+esc(site.title)+'</h1><p>'+esc(site.subtitle)+'</p></div><div class="actions">'+(site.menu||[]).map(m=>'<button data-page="'+esc(['shop','advisor','cart','account'].includes(m.target)?m.target:'shop')+'">'+esc(m.label)+'</button>').join('')+'</div>'+(site.blocks||[]).map(b=>'<div class="block"><h2>'+esc(b.title)+'</h2><p>'+esc(b.text)+'</p>'+image(media.find(m=>m.id===b.image)?.image)+'</div>').join('')}

function profileDate(n){return n?new Date(n*1000).toLocaleString(lang==='ar'?'ar':'en'):'—'}
function profileAvatar(p){let a=String(p.avatar||'');if(/^data:image\/jpeg;base64,[A-Za-z0-9+/]+={0,2}$/.test(a)&&a.length<=180000)return '<img class="personal-avatar" src="'+esc(a)+'" alt="'+esc(t('الصورة الشخصية','Profile picture'))+'">';return '<div class="personal-avatar personal-initial" aria-hidden="true">'+esc(Array.from(p.name||p.email||'?')[0].toUpperCase())+'</div>'}
async function makeAvatar(file){if(!file||!file.size)return undefined;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5000000)throw Error(t('اختر صورة JPG أو PNG أو WebP لا تتجاوز 5 MB','Choose a JPG, PNG or WebP image up to 5 MB'));
 let url=URL.createObjectURL(file);try{let pic=new Image;await new Promise((ok,no)=>{pic.onload=ok;pic.onerror=()=>no(Error(t('تعذر قراءة الصورة','Invalid image')));pic.src=url});let w=pic.naturalWidth,h=pic.naturalHeight;if(!w||!h||w*h>40000000)throw Error(t('أبعاد الصورة كبيرة جداً','Image dimensions are too large'));let canvas=document.createElement('canvas');canvas.width=canvas.height=256;let ctx=canvas.getContext('2d'),side=Math.min(w,h);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,256,256);ctx.drawImage(pic,(w-side)/2,(h-side)/2,side,side,0,0,256,256);let out=canvas.toDataURL('image/jpeg',.82);if(out.length>180000)throw Error('Image too large');return out}finally{URL.revokeObjectURL(url)}}
