document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let p=b.dataset.page,a=b.dataset.act,id=b.dataset.id;if(p){tsNavigate();page=p;render();return}if(!a)return;act(async()=>{if(a.startsWith('staff-')){await tsStaffAction(a,id);return}if(a.startsWith('store-')){await tsStoreAction(a,id);return}if(a.startsWith('biz-')){await tsBusinessAction(a,id);return}if(a.startsWith('inv-')){await tsInvoiceAction(a,id,b);return}if(a==='product-detail'){await tsProductAction(a,id);return}if(a==='sync-confirm-online'){await tsPendingCheck(id);return}if(a.startsWith('sync-')){await tsSyncAction(a,id);return}if(a.startsWith('push-')){await tsPushAction(a);return}if(a.startsWith('ops-')){await tsOpsAction(a,id);return}if(a.startsWith('pro-')){await proAction(a,id);return}else if(a==='logout'||a==='logout-all'){if(a==='logout-all'&&!confirm(t('تسجيل الخروج من جميع الأجهزة؟','Sign out on all devices?')))return;if(tsSyncRunning)throw Error(t('المزامنة جارية','Sync in progress'));await tsPushDisable().catch(()=>{});await api('logout',{scope:a==='logout-all'?'global':'local'});tsSyncLock();tsCartClear();proReset();tsOpsReset();tsInvoiceReset();tsBusinessReset();tsStoreGalleryMap={};tsStoreProducts=[];tsStorePicked='';tsSupplierPending=null;tsPurchasePending=null;tsProductReset();tsMfaGate=null;tsMfaEnrollment=null;user=null;cart=Object.create(null);page='shop'}else if(a==='logout-others'){if(!confirm(t('تسجيل الخروج من الأجهزة الأخرى؟','Sign out other devices?')))return;await api('logout',{scope:'others'});msg(t('تم طلب إنهاء الجلسات الأخرى','Other sessions revoked'));return}else if(a==='remove-avatar'){if(!confirm(t('حذف الصورة الشخصية؟','Remove profile photo?')))return;await api('profile',{avatar:''})}else if(a==='signin'){page='signin'}else if(a==='add'){let p=catalog.products.find(x=>x.id===id);if(!p||p.qty<1+(cart[id]||0))throw Error(t('غير متوفر','Unavailable'));cart[id]=(cart[id]||0)+1;nav();msg(t('تمت الإضافة','Added'));return}else if(a==='remove'){if(--cart[id]<=0)delete cart[id]}else if(a==='active'){let [uid,on]=id.split('|');await api('users/active',{id:uid,active:on==='1'})}else if(a==='pay'){let n=prompt(t('قيمة الدفعة بالدولار','Payment in USD'));if(n===null)return;await api('operation',{kind:page,id,amount:n})}else if(a==='orderstatus'){let [oid,status]=id.split('|');if(status==='cancelled'&&!confirm(t('إلغاء الطلب؟','Cancel order?')))return;if(status==='delivered'&&!confirm(t('تأكيد التسليم واستلام كامل مبلغ الطلب؟ ستصدر فاتورة تلقائياً.','Confirm delivery and full payment? An invoice will be issued automatically.')))return;await api('operation',{kind:'orders',id:oid,status})}else if(a==='blockadd'){draft.blocks.push({title:'',text:'',image:''})}else if(a==='blockremove'){draft.blocks.splice(+id,1)}else if(a==='up'||a==='down'){let i=+id,j=i+(a==='up'?-1:1);if(j>=0&&j<draft.blocks.length)[draft.blocks[i],draft.blocks[j]]=[draft.blocks[j],draft.blocks[i]]}else if(a==='menuadd'){draft.menu.push({label:'',target:'shop'})}else if(a==='menuremove'){draft.menu.splice(+id,1)}else if(a==='preview'){let m=await api('records/media');$('#preview').innerHTML=publishedView(draft,m);return}else if(a==='draftsave'){await api('records',{kind:'draft',...draft,blocks:JSON.stringify(draft.blocks),menu:JSON.stringify(draft.menu)})}else if(a==='editdraft'){let d=(await api('records/draft')).find(x=>x.id===id);draft={title:d.title,subtitle:d.subtitle,accent:d.accent,blocks:d.blocks,menu:d.menu}}else if(a==='publish'||a==='restore'){if(!confirm(t('نشر للزبائن؟','Publish to customers?')))return;await api(a,{id})}else if(a==='printreceipt'){let w=window.open('','_blank');if(!w)throw Error('Allow popups');w.document.write('<meta charset="utf-8">'+$('#receipt').innerHTML);w.document.close();w.print();return}else if(a==='barcode'){let w=window.open('','_blank');if(!w)throw Error('Allow popups');w.document.write('<meta charset="utf-8"><h2>'+esc(id)+'</h2>'+code39(id));w.document.close();w.print();return}await render()})});
document.addEventListener('input',e=>{let n=e.target;if(n.id==='search'){let q=n.value.trim().toLowerCase();$('#catalog').innerHTML=catalogTiles(catalog.products.filter(p=>[p.name,p.nameEn,p.type,p.sku,p.brand,p.model,p.category,p.variant,p.description,...Object.values(p.specs||{})].some(v=>String(v||'').toLowerCase().includes(q))))}if(n.dataset.draft)draft[n.dataset.draft]=n.value;if(n.dataset.key){let b=n.closest('[data-block]'),m=n.closest('[data-menu]');if(b)draft.blocks[+b.dataset.block][n.dataset.key]=n.value;if(m)draft.menu[+m.dataset.menu][n.dataset.key]=n.value}});
document.addEventListener('change',e=>{let n=e.target;if(n.dataset.repair)act(async()=>{await api('operation',{kind:'repairs',id:n.dataset.repair,status:n.value});await render()});if(n.name==='scan'&&n.value)act(async()=>{let st=await api('stock'),p=st.products.find(p=>p.sku===n.value);if(p)n.form.elements.product.value=p.id;else msg(t('الباركود غير موجود','Barcode not found'))})});
let drag=-1;document.addEventListener('dragstart',e=>{let b=e.target.closest('[data-block]');if(b){drag=+b.dataset.block;e.dataTransfer.setData('text/plain',String(drag))}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-block]'))e.preventDefault()});document.addEventListener('drop',e=>{let b=e.target.closest('[data-block]');if(!b||drag<0)return;e.preventDefault();let [x]=draft.blocks.splice(drag,1);draft.blocks.splice(+b.dataset.block,0,x);drag=-1;render()});
document.addEventListener('submit',e=>{let f=e.target,k=f.dataset.form;if(!k)return;e.preventDefault();act(async()=>{let d=Object.fromEntries(new FormData(f));if(k.startsWith('mfa-')){await tsMfaSubmit(k,d);return}if(k.startsWith('staff-')){await tsStaffSubmit(k,d);return}if(k.startsWith('store-')){await tsStoreSubmit(k,d,f);return}if(k==='operation:purchases'){await tsIntegratedPurchase(d);return}if(k.startsWith('supplier-')){await tsSupplierSubmit(k,d);return}if(k.startsWith('biz-')){await tsBusinessSubmit(k,d);return}if(k.startsWith('inv-')){await tsInvoiceSubmit(k,d,f);return}if(k.startsWith('sync-')){await tsSyncSubmit(k,d);return}if(k.startsWith('ops-')){await tsOpsSubmit(k,d);return}if(k.startsWith('pro-')){await proSubmit(k,d,f);return}if(k==='profile'){let avatar=await makeAvatar(d.avatarFile);let p=await api('profile',{name:d.name,phone:d.phone,...(avatar===undefined?{}:{avatar})});user.name=p.name;await render();msg(t('تم حفظ بيانات الحساب','Account details saved'));return}if(k==='email'){await api('email',{email:d.email});await render();msg(t('تم طلب تعديل البريد. راجع رسائل التأكيد.','Email change requested. Check confirmation messages.'));return}if(k==='password'){if(d.password!==d.confirm)throw Error(t('كلمتا المرور غير متطابقتين','Passwords do not match'));if(tsSyncRunning)throw Error('Sync in progress');await tsPushDisable().catch(()=>{});await api('password',d);tsSyncLock();tsCartClear();proReset();tsOpsReset();tsInvoiceReset();tsBusinessReset();tsStoreGalleryMap={};tsStoreProducts=[];tsStorePicked='';tsSupplierPending=null;tsPurchasePending=null;tsMfaGate=null;tsMfaEnrollment=null;user=null;cart=Object.create(null);page='signin';await render();msg(t('تم تغيير كلمة المرور، سجل الدخول بالجديدة.','Password changed. Sign in with your new password.'));return}if(k==='login'||k==='register'){let result=await api(k,d);if(result?.confirmationRequired){user=null;page='signin';await render();msg(t('راجع بريدك الإلكتروني لتأكيد الحساب ثم سجل الدخول.','Confirm your email, then sign in.'));return}if(result?.mfaRequired){user=null;tsMfaGate=result.mfa;tsMfaEnrollment=null;tsSyncLock();page='signin';await render();return}tsMfaGate=null;tsMfaEnrollment=null;user=result;if(tsSyncVault?.owner!==user.id||tsSyncVault?.role!==user.role)tsSyncLock();page=tsSyncVault&&tsSyncKinds[user.role]?'sync':user.role==='customer'?'shop':'home';if(tsSyncCanReplay())tsSyncReplay().catch(e=>msg(e.message))}else if(k==='order'){let o=await api('order',{...d,items:orderPayload()});cart=Object.create(null);page='account';msg(t('تم الطلب: ','Order placed: ')+o.id)}else if(k==='pos'){let r=await api('pos',d);$('#receipt').innerHTML='<h2>'+esc(r.number)+'</h2><p>'+esc(r.items[0].name)+' × '+esc(r.items[0].qty)+' · '+money(r.total)+'</p><button type="button" data-act="printreceipt">'+t('طباعة','Print')+'</button>';f.querySelector('button').disabled=true;msg(t('تم البيع','Sale saved'));return}else if(k==='warranty'){await api('warranty',d)}else if(k==='user'){await api('users',d)}else if(k==='media'){let file=d.file;if(file.size>350000)throw Error('File too large');let image=await new Promise((res,rej)=>{let r=new FileReader;r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});await api('records',{kind:'media',name:d.name,image})}else if(k==='advisor'){let p=catalog.products.filter(x=>x.type===d.type&&x.qty>0&&x.price<=Number(d.budget));let keyword=d.keyword.toLowerCase();p.sort((a,b)=>(Number(JSON.stringify(b).toLowerCase().includes(keyword))-Number(JSON.stringify(a).toLowerCase().includes(keyword)))||a.price-b.price);$('#advice').innerHTML='<div class="grid">'+p.slice(0,5).map(productCard).join('')+'</div>';return}else if(k.startsWith('record:')){await api('records',{...d,kind:k.split(':')[1]})}else if(k.startsWith('operation:')){await api('operation',{...d,kind:k.split(':')[1]})}await render();msg(t('تم التنفيذ','Done'))})});
