(async()=>{try{if(window.tsCloud.isRecovery()){page='recover';await render();return}if(!navigator.onLine){tsCartLoad();try{if(await tsSyncRead())page='sync'}catch{}await render();return}let result=await api('me');if(result?.mfaRequired){user=null;tsMfaGate=result.mfa;page='signin';await render();return}user=result;tsCartLoad();if(user&&user.role!=='customer')page='home';await render()}catch(e){nav();main.innerHTML=card(t('النسخة السحابية غير متصلة','Cloud backend not connected'),info(e.message)+'<a class="button" href="./index.html?demo=1">'+t('فتح النسخة التجريبية المحلية','Open local demo')+'</a>')}})();

function code39(value){let v=value.toUpperCase(),alphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%',enc=[0x034,0x121,0x061,0x160,0x031,0x130,0x070,0x025,0x124,0x064,0x109,0x049,0x148,0x019,0x118,0x058,0x00d,0x10c,0x04c,0x01c,0x103,0x043,0x142,0x013,0x112,0x052,0x007,0x106,0x046,0x016,0x181,0x0c1,0x1c0,0x091,0x190,0x0d0,0x085,0x184,0x0c4,0x0a8,0x0a2,0x08a,0x02a];if(!v||[...v].some(c=>!alphabet.includes(c)))return '<p>Unsupported Code 39 characters</p>';let x=20,bars='';for(let c of '*'+v+'*'){let n=c==='*'?0x094:enc[alphabet.indexOf(c)];for(let i=0;i<9;i++){let w=(n&(1<<(8-i)))?6:2;if(i%2===0)bars+='<rect x="'+x+'" y="0" width="'+w+'" height="65"/>';x+=w}x+=2}return '<svg xmlns="http://www.w3.org/2000/svg" width="'+(x+20)+'" height="65" viewBox="0 0 '+(x+20)+' 65" fill="black">'+bars+'</svg>'}
