/* Theme preference is local to this browser; it never changes business data. */
(function(){
 const root=document.documentElement,button=document.getElementById('ts-theme');if(!button)return;
 let mode='light';try{mode=localStorage.getItem('ts-theme-v41')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{}
 function apply(){root.dataset.theme=mode;const ar=root.lang==='ar';button.textContent=mode==='dark'?(ar?'☀ فاتح':'☀ Light'):(ar?'☾ داكن':'☾ Dark');button.setAttribute('aria-pressed',String(mode==='dark'));button.setAttribute('aria-label',ar?'تبديل الوضع الليلي':'Toggle dark mode')}
 button.addEventListener('click',()=>{mode=mode==='dark'?'light':'dark';try{localStorage.setItem('ts-theme-v41',mode)}catch{}apply()});
 new MutationObserver(apply).observe(root,{attributes:true,attributeFilter:['lang']});apply();
})();

/* Owner-controlled optional TOTP policy in the existing account/security page. */
function tsMfaMarkup(m,gate){let verified=(m.factors||[]).filter(f=>f.type==='totp'&&f.status==='verified'),unverified=(m.factors||[]).filter(f=>f.type==='totp'&&f.status==='unverified'),out=info(m.elevated?t('تم التحقق الثنائي في هذه الجلسة','Two-factor verified in this session'):m.required?t('يلزم التحقق الثنائي قبل المتابعة','Two-factor verification required before continuing'):t('المصادقة الثنائية اختيارية حاليًا','Two-factor authentication is optional'));
let codeField=input('code','رمز تطبيق المصادقة (6 أرقام)','Authenticator code (6 digits)','text','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"');
if(tsMfaEnrollment){let e=tsMfaEnrollment;out+=info(t('أضف حسابًا يدويًا في تطبيق المصادقة باستخدام مفتاح الإعداد التالي (لا تشاركه).','Add an account manually in your authenticator app using this setup key. Keep it private.'))+'<p dir="ltr"><code>'+esc(e.secret)+'</code></p>'+form('mfa-verify','<input type="hidden" name="id" value="'+esc(e.id)+'">'+codeField)}
else if(verified.length&&!m.elevated)out+=form('mfa-verify',select('id','تطبيق المصادقة','Authenticator',verified.map(f=>[f.id,f.name||'TOTP']))+codeField);
else if(!m.verified||m.elevated)out+=form('mfa-start',input('name','اسم الجهاز','Device name','text','TechStore','required maxlength="64"'))+info(t('أضف تطبيق مصادقة جديدًا. يفضل جهاز احتياطي قبل فرض السياسة.','Add an authenticator. A backup authenticator is recommended before enforcing the policy.'));
if(!tsMfaEnrollment&&unverified.length)out+=form('mfa-remove',select('id','إزالة إعداد غير مكتمل','Remove incomplete setup',unverified.map(f=>[f.id,f.name||'TOTP'])));
if(!gate&&m.elevated&&verified.length)out+=form('mfa-remove',select('id','إزالة تطبيق مصادقة','Remove authenticator',verified.map(f=>[f.id,f.name||'TOTP'])));
if(!gate&&m.role==='admin'){out+=info(t('سياسة المالك الحالية: ','Owner policy: ')+({optional:t('اختياري','Optional'),admin:t('إلزام الإدارة','Require admins'),staff:t('إلزام الإدارة والموظفين','Require staff')}[m.mode]||''));out+=m.elevated?form('mfa-policy',select('mode','سياسة المصادقة الثنائية','Two-factor policy',[[m.mode,{optional:t('اختياري','Optional'),admin:t('إلزام الإدارة','Require admins'),staff:t('إلزام الإدارة والموظفين','Require staff')}[m.mode]],...['optional','admin','staff'].filter(v=>v!==m.mode).map(v=>[v,{optional:t('اختياري','Optional'),admin:t('إلزام الإدارة','Require admins'),staff:t('إلزام الإدارة والموظفين','Require staff')}[v]])])):info(t('فعّل تطبيق المصادقة لحسابك وأدخل رمز التحقق قبل تعديل السياسة.','Verify your own authenticator before changing policy.'));out+=proNote(t('الوضع الاختياري لا يزيل تطبيقات المصادقة المرتبطة. الزبائن غير ملزمين بالسياسة العامة.','Optional mode does not remove enrolled authenticators. Customers are not subject to the mandatory policy.'))}
if(gate)out+=form('mfa-cancel',info(t('إلغاء تسجيل الدخول','Cancel sign-in')));return card(t('المصادقة الثنائية (2FA)','Two-factor authentication (2FA)'),out)}
async function tsMfaSubmit(k,d){if(k==='mfa-cancel'){await api('logout');tsMfaGate=null;tsMfaEnrollment=null;user=null;page='signin';await render();return}
if(k==='mfa-start'){if(tsMfaEnrollment)throw Error('Complete the pending setup');let x=await api('mfa-enroll',{name:d.name});if(!x?.id||!x?.totp?.secret)throw Error('Authenticator setup unavailable');tsMfaEnrollment={id:x.id,secret:x.totp.secret};if(tsMfaGate)tsMfaGate=await api('mfa-status');await render();return}
if(k==='mfa-verify'){let status=await api('mfa-verify',{id:d.id,code:d.code});if(!status.elevated)throw Error('Verification not confirmed');tsMfaEnrollment=null;if(tsMfaGate){let result=await api('me');if(!result||result.mfaRequired)throw Error('Sign in verification unavailable');user=result;tsMfaGate=null;tsSyncLock();tsCartLoad();page=user.role==='customer'?'shop':'home'}await render();msg(t('تم التحقق','Verified'));return}
if(k==='mfa-remove'){if(!confirm(t('إزالة تطبيق المصادقة المحدد؟','Remove selected authenticator?')))return;let status=await api('mfa-remove',{id:d.id});tsMfaEnrollment=null;if(tsMfaGate)tsMfaGate=status;await render();return}
if(k==='mfa-policy'){if(!confirm(t('تغيير سياسة المصادقة لجميع الحسابات المشمولة؟','Change authentication policy for affected accounts?')))return;await api('mfa-policy',{mode:d.mode});await render();msg(t('تم حفظ سياسة الأمان','Security policy saved'));return}}
